class Solution {
    public int countTriplets(int[] nums){
        Map<Integer,Integer> frequency=new HashMap<>();
        for(int a:nums)for(int b:nums)frequency.merge(a&b,1,Integer::sum);
        int answer=0;
        for(int value:nums)for(Map.Entry<Integer,Integer> entry:frequency.entrySet())if((entry.getKey()&value)==0)answer+=entry.getValue();
        return answer;
    }
}

code.kotlin:
class Solution {
    fun countTriplets(nums:IntArray):Int{
        val frequency=mutableMapOf<Int,Int>();
        for(a in nums)for(b in nums)frequency[a and b]=(frequency[a and b]?:0)+1;
        var answer=0;
        for(value in nums)for((mask,count) in frequency)if(mask and value==0)answer+=count;
        return answer
    }
}

code.cpp:
class Solution {
    public: int countTriplets(vector<int>& nums){
        unordered_map<int,int> frequency;
        for(int a:nums)for(int b:nums)++frequency[a&b];
        int answer=0;
        for(int value:nums)for(auto [mask,count]:frequency)if((mask&value)==0)answer+=count;
        return answer;
    }
};
